 void checkArtwork(FrameLayout hero,int token,int tries){if(token!=a.epoch||a.detailChrome!=this||!a.detailPage||a.isFinishing())return;if(artwork.getDrawable()!=null){artworkState.setVisibility(View.GONE);return;}if(tries<14){artwork.postDelayed(()->checkArtwork(hero,token,tries+1),1500);return;}hero.getLayoutParams().height=a.safeTop+dp(110);hero.requestLayout();artworkState.setText("封面加载失败 · 点击重试");hero.setOnClickListener(v->{a.openingMeta=meta;a.detail(id,type);});}
 String trackLabel(boolean audio){JSONObject s=picked();String key=audio?"mp.audioLabel":"mp.subtitleLabel";if(s!=null&&!s.optString(key).isEmpty())return s.optString(key);return audio?PlaybackPrefs.AUDIO_LABELS[PlaybackPrefs.index(PlaybackPrefs.AUDIO,PlaybackPrefs.audio(a.prefs))]:PlaybackPrefs.SUB_LABELS[PlaybackPrefs.index(PlaybackPrefs.SUBS,PlaybackPrefs.subtitle(a.prefs))];}
 void trackMenu(boolean audio){JSONObject source=picked();if(source==null){if(audio)audioPreference();else subtitlePreference();return;}JSONObject tracks=source.optJSONObject("mp.tracks");if(tracks!=null){chooseTrack(source,tracks,audio);return;}if(readingTracks)return;readingTracks=true;final boolean[] cancelled={false};ProgressDialog wait=ProgressDialog.show(a,"读取真实轨道","正在读取视频中的音轨和字幕，最长约 11 秒…",true,true);final int token=a.epoch;Thread worker=new Thread(()->{JSONObject found=null;String error="";try{found=SourceTracks.inspect(a.getApplicationContext(),source);}catch(Exception e){error=e.getMessage()==null?"此片源暂时无法预读轨道":e.getMessage();}catch(LinkageError e){error="当前设备无法预读轨道，可直接开播后选择";}final JSONObject result=found;final String reason=error;a.runOnUiThread(()->{readingTracks=false;if(wait.isShowing())wait.dismiss();if(cancelled[0]||token!=a.epoch||a.detailChrome!=this||a.isFinishing())return;if(result!=null){try{source.put("mp.tracks",result);}catch(Exception ignored){}chooseTrack(source,result,audio);}else new AlertDialog.Builder(a).setTitle("轨道尚未就绪").setMessage(reason).setPositiveButton("设置语言偏好",(d,n)->{if(audio)audioPreference();else subtitlePreference();}).setNegativeButton("关闭",null).show();});},"source-track-probe");wait.setOnCancelListener(d->{cancelled[0]=true;worker.interrupt();});worker.start();}
 void chooseTrack(JSONObject source,JSONObject tracks,boolean audio){JSONArray choices=tracks.optJSONArray(audio?"audio":"subtitles");if(choices==null)choices=new JSONArray();final JSONArray items=choices;String[] labels=new String[items.length()+1];labels[0]=audio?"自动（片源默认）":"关闭内嵌字幕";for(int i=0;i<items.length();i++)labels[i+1]=items.optJSONObject(i).optString("label");int selected=-1;String key=audio?"mp.audioTrack":"mp.subtitleTrack";if(source.has(key)){int id=source.optInt(key,-1);selected=0;for(int i=0;i<items.length();i++)if(items.optJSONObject(i).optInt("id")==id)selected=i+1;}new AlertDialog.Builder(a).setTitle((audio?"真实音轨":"真实内嵌字幕")+" · "+items.length()+" 条").setSingleChoiceItems(labels,selected,(d,n)->{try{if(audio&&n==0){source.remove(key);source.remove("mp.audioLabel");}else{source.put(key,n==0?-1:items.optJSONObject(n-1).optInt("id"));source.put(audio?"mp.audioLabel":"mp.subtitleLabel",labels[n]);}}catch(Exception ignored){}d.dismiss();rerender();}).setNeutralButton("语言偏好",(d,n)->{if(audio)audioPreference();else subtitlePreference();}).setNegativeButton("取消",null).show();}
 void audioPreference(){new AlertDialog.Builder(a).setTitle("音轨语言偏好").setSingleChoiceItems(PlaybackPrefs.AUDIO_LABELS,PlaybackPrefs.index(PlaybackPrefs.AUDIO,PlaybackPrefs.audio(a.prefs)),(d,n)->{a.prefs.edit().putString("pref.audio",PlaybackPrefs.AUDIO[n]).apply();d.dismiss();rerender();}).setNeutralButton("实际音轨说明",(d,n)->new AlertDialog.Builder(a).setMessage("真实音轨需要打开视频后由播放器读取，可在播放菜单中选择；这里设置开播后的优先语言。").setPositiveButton("知道了",null).show()).show();}
