 String sourceText(){JSONObject s=picked();if(s==null)return "选择播放源";StreamInfo i=StreamInfo.parse(s);String name=!i.file.isEmpty()?i.file:s.optString("title",s.optString("name","片源")).split("\n")[0];List<String> t=i.tags(StreamInfo.minutes(meta.optString("runtime")));return name+(t.isEmpty()?"":"\n"+String.join(" / ",t));}
